//! 持久化存储：集合、当前数据状态与不可变版本快照。
//!
//! 持久化采用“快照文件 + 追加式 WAL”：
//! - `snapshot.json` 以原子重命名落盘，固化保存版本那一刻各集合的数据；
//! - `wal.log` 逐行记录已确认提交的批量写入（每行一个 JSON）；
//! - 启动时先恢复快照，再重放后续 WAL；末尾若存在崩溃导致的残缺行则截断，
//!   因此未完成（未 fsync）的写入在重启后不会留下任何记录。

use serde::{Deserialize, Serialize};
use serde::Deserializer;
use serde_json::{Map, Value};
use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

/// 记录字段允许的值类型：字符串、整数、布尔、null 或嵌套对象。
/// 反序列化时拒绝数字中的浮点数以及数组，同时保留首次写入的字段顺序。
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(transparent)]
pub struct RecordValue(#[serde(deserialize_with = "validate_value")] Value);

impl RecordValue {
    pub fn as_value(&self) -> &Value {
        &self.0
    }
}

/// 一条记录即一个保留字段顺序的 JSON 对象，主键为其中 `id` 字段。
pub type Record = Map<String, Value>;

/// 一次写入校验失败：定位到批次内的记录位置、主键（若能识别）与具体原因。
#[derive(Debug, Clone, Serialize)]
pub struct WriteError {
    pub index: usize,
    pub id: Option<String>,
    pub reason: String,
}

#[derive(Debug, Clone, Copy)]
pub enum StoreError {
    VersionNotFound,
    CollectionNotFound,
    PersistenceFailed,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "event", rename_all = "snake_case")]
enum WalEvent {
    /// 已确认提交的一批记录（全有或全无）。
    Commit { collection: String, records: Vec<Record> },
    /// 某个集合数据已整体替换为快照状态（即新版本保存后的压缩点）。
    Snapshot { versions: Vec<SavedVersion>, collections: Vec<CollectionState> },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CollectionState {
    name: String,
    #[serde(rename = "2")]
    _ph: Option<Value>,
    records: Vec<Record>,
}

impl CollectionState {
    fn new(name: String) -> Self {
        CollectionState { name, _ph: None, records: Vec::new() }
    }
}

/// 一个已保存的版本（只读快照）。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SavedVersion {
    pub id: u64,
    #[serde(rename = "saved_at")]
    pub saved_at_ms: u64,
    /// 保存时各集合的完整数据，加载后转为按名索引。
    #[serde(rename = "collections")]
    snapshot_raw: Option<Vec<CollectionState>>,
    #[serde(skip)]
    pub snapshot: HashMap<String, Vec<Record>>,
}

#[derive(Debug, Default)]
struct CurrentState {
    collections: BTreeMap<String, Vec<Record>>,
}

/// 整个服务的状态：单把锁串行化所有提交与保存，保证线性一致。
pub struct Store {
    inner: Mutex<Inner>,
    data_dir: PathBuf,
}

struct Inner {
    current: CurrentState,
    versions: Vec<SavedVersion>,
    next_id: u64,
    /// 当前磁盘状态对应的 WAL 起点：snapshot 事件覆盖此序号之前的全部历史。
    wal_base: u64,
    wal_file: Option<fs::File>,
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .save(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

impl Store {
    /// 从数据目录加载或初始化存储，并完成恢复。
    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
        let dir = data_dir.as_ref();
        fs::create_dir_all(dir).map_err(|e| format!("create data dir: {e}"))?;

        let mut inner = Inner {
            current: CurrentState::default(),
            versions: Vec::new(),
            next_id: 1,
            wal_base: 0,
            wal_file: None,
        };

        // 1. 恢复最近一次快照（若存在）。
        let snap_path = dir.join("snapshot.json");
        if snap_path.exists() {
            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
            let data: SnapshotFile = serde_json::from_slice(&bytes)
                .map_err(|e| format!("parse snapshot: {e}"))?;
            inner.versions = data.versions;
            for c in data.collections {
                inner.current.collections.insert(c.name, c.records);
            }
            inner.next_id = inner.versions.last().map(|v| v.id + 1).unwrap_or(1);
        }

        // 2. 重放 snapshot 之后的 WAL。
        let wal_path = dir.join("wal.log");
        if wal_path.exists() {
            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
            let mut valid_bytes = 0usize;
            for (i, line) in content.split('\n').enumerate() {
                if line.is_empty() {
                    if i == 0 && content.is_empty() {
                        break;
                    }
                    // 空行可能是末尾换行或中间的脏数据；只接受文件末尾恰好一个换行。
                    continue;
                }
                match serde_json::from_str::<WalEvent>(line) {
                    Ok(event) => {
                        inner.apply(event);
                        valid_bytes += line.len() + 1;
                    }
                    Err(_) => {
                        // 崩溃残留的不完整行：截断到最后一个完整事件之后。
                        break;
                    }
                }
            }
            // 截断残缺行（含其后续内容），保证再次启动结果一致。
            if valid_bytes < content.len() {
                let mut f = fs::OpenOptions::new()
                    .write(true)
                    .truncate(false)
                    .open(&wal_path)
                    .map_err(|e| format!("repair wal: {e}"))?;
                f.set_len(valid_bytes as u64)
                    .map_err(|e| format!("repair wal: {e}"))?;
            }
        }

        // 3. 打开 WAL 供后续追加。
        let wal_file = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&wal_path)
            .map_err(|e| format!("open wal: {e}"))?;
        inner.wal_file = Some(wal_file);
        inner.wal_base = 0;

        Ok(Store {
            inner: Mutex::new(inner),
            data_dir: dir.to_path_buf(),
        })
    }

    /// 批量写入：校验整批后原子提交，任一条不合法则整批拒绝。
    pub fn write_batch(
        &self,
        collection: &str,
        batch: Vec<Value>,
    ) -> Result<WriteOk, WriteError> {
        if collection.is_empty() {
            return Err(WriteError {
                index: 0,
                id: None,
                reason: "collection name must not be empty".to_string(),
            });
        }
        let mut st = self.inner.lock().unwrap();

        // 阶段 1：逐条校验，任何失败都不修改状态。
        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(batch.len());
        let mut prepared: Vec<Record> = Vec::with_capacity(batch.len());
        for (i, raw) in batch.iter().enumerate() {
            let rec = match raw {
                Value::Object(map) => map,
                _ => {
                    return Err(WriteError {
                        index: i,
                        id: None,
                        reason: "record must be a JSON object".to_string(),
                    });
                }
            };
            let id_val = match rec.get("id") {
                Some(v) => v,
                None => {
                    return Err(WriteError {
                        index: i,
                        id: None,
                        reason: "missing primary key field \"id\"".to_string(),
                    });
                }
            };
            let id = match id_val {
                Value::String(s) if !s.is_empty() => s.as_str(),
                Value::String(_) => {
                    return Err(WriteError {
                        index: i,
                        id: None,
                        reason: "primary key \"id\" must be a non-empty string".to_string(),
                    });
                }
                _ => {
                    return Err(WriteError {
                        index: i,
                        id: None,
                        reason: "primary key \"id\" must be a string".to_string(),
                    });
                }
            };
            if let Some(&prev) = seen.get(id) {
                return Err(WriteError {
                    index: i,
                    id: Some(id.to_string()),
                    reason: format!("duplicate id \"{id}\" in same batch (first at index {prev})"),
                });
            }

            // 校验值类型：字符串/整数/布尔/null/嵌套对象；递归校验嵌套对象。
            for (k, v) in rec.iter() {
                if let Err(msg) = validate_field_value(v) {
                    return Err(WriteError {
                        index: i,
                        id: Some(id.to_string()),
                        reason: format!("field \"{k}\": {msg}"),
                    });
                }
            }

            seen.insert(id, i);
            prepared.push(rec.clone());
        }

        // 阶段 2：与已有数据比对——主键冲突即“不同结构的记录”按要求拒绝。
        let existing = st.current.collections.entry(collection.to_string()).or_default();
        let mut existing_index: HashMap<&str, usize> =
            existing.iter().enumerate().map(|(i, r)| (r["id"].as_str().unwrap(), i)).collect();
        for (i, rec) in prepared.iter().enumerate() {
            let id = rec["id"].as_str().unwrap();
            if let Some(&ei) = existing_index.get(id) {
                if &existing[ei] != rec {
                    return Err(WriteError {
                        index: i,
                        id: Some(id.to_string()),
                        reason: format!(
                            "collection \"{collection}\" already contains a different record with id \"{id}\""
                        ),
                    });
                }
            }
        }

        // 阶段 3：提交——先追加 WAL 并 fsync，再更新内存。
        let event = WalEvent::Commit {
            collection: collection.to_string(),
            records: prepared.clone(),
        };
        if let Err(e) = st.append_wal(&event) {
            return Err(WriteError {
                index: 0,
                id: None,
                reason: format!("persistence failed: {e}"),
            });
        }

        let mut inserted = 0usize;
        for rec in prepared {
            let id = rec["id"].as_str().unwrap();
            if let Some(&ei) = existing_index.get(id) {
                existing[ei] = rec; // 内容相同（阶段2保证），等于 no-op
            } else {
                existing_index.insert(id, existing.len());
                existing.push(rec);
                inserted += 1;
            }
        }

        Ok(WriteOk {
            collection: collection.to_string(),
            accepted: batch.len(),
            inserted,
        })
    }

    /// 保存当前时刻各集合数据为只读版本快照。
    pub fn save_version(&self) -> Result<SavedVersionSummary, String> {
        let mut st = self.inner.lock().unwrap();
        let id = st.next_id;
        let snapshot: HashMap<String, Vec<Record>> = st
            .current
            .collections
            .clone()
            .into_iter()
            .collect();
        let version = SavedVersion::new(id, now_ms(), snapshot);
        st.versions.push(version.clone());
        st.next_id += 1;

        // 固化所有版本与当前数据，并把 WAL 压缩到新压缩点。
        st.compact(&self.data_dir)?;
        Ok(SavedVersionSummary {
            id: version.id,
            saved_at: version.saved_at_ms,
        })
    }

    /// 查询指定版本中指定集合的全部记录（字段顺序与写入时一致）。
    pub fn read_version_collection(
        &self,
        version_id: u64,
        collection: &str,
    ) -> Result<Vec<Record>, StoreError> {
        let st = self.inner.lock().unwrap();
        let version = st
            .versions
            .iter()
            .find(|v| v.id == version_id)
            .ok_or(StoreError::VersionNotFound)?;
        version
            .snapshot
            .get(collection)
            .cloned()
            .ok_or(StoreError::CollectionNotFound)
        // 注意：快照内记录的字段顺序来自首次写入并随序列化保留。
    }

    /// 已保存版本的摘要列表（按保存顺序）。
    pub fn list_versions(&self) -> Vec<SavedVersionSummary> {
        let st = self.inner.lock().unwrap();
        st.versions
            .streaming_iter()
            .map(|v| SavedVersionSummary {
                id: v.id,
                saved_at: v.saved_at_ms,
            })
            .collect()
    }
}

impl Inner {
    fn apply(&mut self, event: WalEvent) {
        match event {
            WalEvent::Commit { collection, records } => {
                let entry = self.current.collections.entry(collection).or_default();
                for rec in records {
                    let id = rec["id"].as_str().unwrap();
                    if let Some(pos) = entry.iter().position(|r| r["id"] == id) {
                        entry[pos] = rec;
                    } else {
                        entry.push(rec);
                    }
                }
            }
            WalEvent::Snapshot { versions, collections } => {
                self.versions = versions;
                self.current.collections.clear();
                for c in collections {
                    self.current.collections.insert(c.name, c.records);
                }
            }
        }
    }

    fn append_wal(&mut self, event: &WalEvent) -> Result<(), String> {
        let mut line = serde_json::to_string(event).map_err(|e| format!("encode wal: {e}"))?;
        line.push('\n');
        let f = self.wal_file.as_mut().ok_or("wal not open")?;
        f.write_all(line.as_bytes())
            .and_then(|_| f.flush())
            .and_then(|_| f.sync_all())
        .map_err(|e| format!("wal append: {e}"))
    }

    /// 写新快照并把 WAL 压缩为单个 snapshot 事件。
    fn compact(&mut self, data_dir: &Path) -> Result<(), String> {
        let collections: Vec<CollectionState> = self
            .current
            .collections
            .clone()
            .into_iter()
            .map(|(name, records)| CollectionState {
                name,
                _ph: None,
                records,
            })
            .map(|mut c| {
                c._ph = None;
                c
            })
            .collect();
        for v in self.versions.iter_mut() {
            v.snapshot_raw = None;
        }
        let snap = SnapshotFile {
            versions: self.versions.clone(),
            collections: collections.clone(),
        };
        // 原子重命名 + 目录 fsync。
        let tmp = data_dir.join("snapshot.json.tmp");
        let mut buf =
            serde_json::to_vec(&snap).map_err(|e| format!("encode snapshot: {e}"))?;
        buf.push(b'\n');
        write_atomic(&data_dir.join("snapshot.json"), &buf)?;

        // 重置 WAL：旧提交已被快照覆盖，仅保留一个 snapshot 标记（便于审计与截断点）。
        let wal_path = data_dir.join("wal.log");
        let marker = WalEvent::Snapshot {
            versions: self.versions.to_vec(),
            collections,
        };
        let mut line =
            serde_json::to_string(&marker).map_err(|e| format!("encode marker: {e}"))?;
        line.push('\n');
        let mut f = fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&wal_path)
            .map_err(|e| format!("reset wal: {e}"))?;
        f.write_all(line.as_bytes())
            .and_then(|_| f.flush())
            .and_then(|_| f.sync_all())
            .map_err(|e| format!("wal marker: {e}"))?;
        self.wal_file = Some(f);
        Ok(())
    }
}

impl SavedVersion {
    fn new(id: u64, saved_at_ms: u64, snapshot: HashMap<String, Vec<Record>>) -> Self {
        SavedVersion {
            id,
            saved_at_ms,
            snapshot_raw: None,
            snapshot,
        }
    }
}

/// 反序列化后把快照中的集合数据填入内存索引，并为没有快照数据的版本保留空映射。
impl std::ops::Deref for SavedVersion {
    type Target = HashMap<String, Vec<Record>>;
    fn deref(&self) -> &Self::Target {
        &self.snapshot
    }
}

fn write_atomic(target: &Path, bytes: &[u8]) -> Result<(), String> {
    let tmp = target.with_extension("json.tmp");
    let parent = target.parent().unwrap_or(Path::open_error()?);
    {
        let mut f = fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&tmp)
            .map_err(|e| format!("write tmp: {e}"))?;
        f.write_all(bytes)
            .and_then(|_| f.flush())
            .and_then(|_| f.sync_all())
            .map_err(|e| format!("write tmp: {e}"))?;
    }
    fs::rename(&tmp, target).map_err(|e| format!("rename snapshot: {e}"))?;
    if let Ok(dir) = fs::OpenOptions::new().read(true).open(parent) {
        let _ = dir.sync_all();
    }
    Ok(())
}

#[derive(Serialize, Deserialize)]
struct SnapshotFile {
    versions: Vec<SavedVersion>,
    collections: Vec<CollectionState>
}

#[derive(Debug, Clone, Serialize)]
pub struct WriteOk {
    pub collection: String,
    pub accepted: usize,
    pub inserted: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct RecordView {
    id: String,
    #[serde(flatten)]
    fields: Value,
}

#[derive(Debug, Clone, Serialize)]
pub struct SavedVersionSummary {
    pub id: u64,
    pub saved_at: u64,
}

/// 递归校验字段值：string/i64/u64/bool/null/object，拒绝 float 与 array。
fn validate_field_value(v: &Value) -> Result<(), String> {
    match v {
        Value::Null | Value::Bool(_) | Value::String(_) => Ok(()),
        Value::Number(n) => {
            if n.is_i64() || n.is_u64() {
                Ok(())
            } else {
                Err("number must be an integer".to_string())
            }
        }
        Value::Object(m) => {
            for (k, child) in m.iter() {
                validate_field_value(child).map_err(|e| format!("{k}: {e}"))?;
            }
            Ok(())
        }
        Value::Array(_) => Err("arrays are not allowed".to_string()),
    }
}

/// serde 用的递归校验（保留 `RecordValue` 类型用于将来强类型入口）。
fn validate_value<'de, D>(deserializer: D) -> Result<Value, D::Error>
where
    D: Deserializer<'de>,
{
    let v = Value::deserialize(deserializer)?;
    validate_field_value(&v).map_err(serde::de::Error::custom)?;
    Ok(v)
}

