        let mut f = fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(wal_path)
            .map_err(|e| format!("truncate wal: {e}"))?;
        f.flush()
            .and_then(|_| f.sync_all())
            .map_err(|e| format!("truncate wal: {e}"))?;
    }
    // 先关闭旧句柄，再以 append 重新打开供后续提交使用。
    let reopened = fs::OpenOptions::new()
        .append(true)
        .open(wal_path)
        .map_err(|e| format!("reopen wal: {e}"))?;
    *wal = reopened;
    Ok(())
}

